#include <vector>
#include <unordered_map>
#include <algorithm>

class Solution {
public:
    int minDiscards(std::vector<int>& inventory, int maxAllowed) {
        std::unordered_map<int, int> counts;
        for (int x : inventory) counts[x]++;

        int discards = 0;
        for (const auto& [item, count] : counts) {
            if (count > maxAllowed) {
                discards += (count - maxAllowed);
            }
        }
        return discards;
    }
};

import java.util.*;

class Solution {
    public int minDiscards(int[] inventory, int maxAllowed) {
        Map<Integer, Integer> counts = new HashMap<>();
        for (int x : inventory) {
            counts.put(x, counts.getOrDefault(x, 0) + 1);
        }

        int discards = 0;
        for (int count : counts.values()) {
            if (count > maxAllowed) {
                discards += (count - maxAllowed);
            }
        }
        return discards;
    }
}

var minDiscards = function(inventory, maxAllowed) {
    const counts = new Map();
    for (const x of inventory) {
        counts.set(x, (counts.get(x) || 0) + 1);
    }

    let discards = 0;
    for (const count of counts.values()) {
        if (count > maxAllowed) {
            discards += (count - maxAllowed);
        }
    }
    return discards;
};
